// Des: Spend guard: free credits first, paid only under cap + go
// Flo: kill switch off? > month credits used > free left covers cost? > else paid part x price must fit capz_usdz_mont and needs go > record real spend
// I/O: Db + Conf + vendor + credit cost + time (ladder) > Deci (allow, paid, micro-USD, reason); ledger rows in vled
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const base = @import("nt-vend-base.zig"); const kill = @import("ru-kill-swit.zig"); const cfgz = @import("cf-conf-load.zig");
pub const Deci = struct { okay: bool, paid: bool = false, micr: u64 = 0, why2: []const u8 = "" };
pub fn montOfzz(mill: i64) i64 { const secs: u64 = @intCast(@max(@divFloor(mill, 1000), 0)); const epsz: std.time.epoch.EpochSeconds = .{ .secs = secs }; const yday = epsz.getEpochDay().calculateYearDay(); return @as(i64, yday.year) * 100 + yday.calculateMonthDay().month.numeric(); }
pub fn freeOfzz(conf: cfgz.Conf, vend: base.Vend) u32 { return switch (vend) { .deco => conf.vend_free_cred.deco, .zenr => conf.vend_free_cred.zenr, .brig => conf.vend_free_cred.brig, .mock => 0 }; }
pub fn pricOfzz(conf: cfgz.Conf, vend: base.Vend) u32 { return switch (vend) { .deco => conf.vend_cred_micr.deco, .zenr => conf.vend_cred_micr.zenr, .brig => conf.vend_cred_micr.brig, .mock => 0 }; }
pub fn spenUsed(dbzz: *sqli.Dbzz, vend: base.Vend, nowz: i64) !i64 { var stmt = try dbzz.prep("SELECT cred FROM vled WHERE vend=?1 AND mont=?2;"); defer stmt.fini(); try stmt.bindText(1, base.vendName(vend)); try stmt.bindIntz(2, montOfzz(nowz)); if (!try stmt.step()) return 0; return stmt.colzIntz(0); }
pub fn spenTota(dbzz: *sqli.Dbzz, nowz: i64) !i64 { var stmt = try dbzz.prep("SELECT coalesce(sum(micr),0) FROM vled WHERE mont=?1;"); defer stmt.fini(); try stmt.bindIntz(1, montOfzz(nowz)); _ = try stmt.step(); return stmt.colzIntz(0); }
pub fn spenChek(dbzz: *sqli.Dbzz, conf: cfgz.Conf, vend: base.Vend, cost: u32, nowz: i64, gozz: bool) !Deci { if (try kill.killGetz(dbzz)) return .{ .okay = false, .why2 = "kill switch on" }; const used = try spenUsed(dbzz, vend, nowz); const free: i64 = freeOfzz(conf, vend); const paid = @max(used + cost - free, 0) - @max(used - free, 0); if (paid == 0) return .{ .okay = true }; const micr: u64 = @intCast(paid * @as(i64, pricOfzz(conf, vend))); if (!gozz) return .{ .okay = false, .why2 = "free credits used up, paid needs go" }; const cap2 = cfgz.capzMicr(conf); const tota: u64 = @intCast(try spenTota(dbzz, nowz)); if (cap2 == 0 or tota + micr > cap2) return .{ .okay = false, .why2 = "over capz_usdz_mont" }; return .{ .okay = true, .paid = true, .micr = micr }; }
pub fn spenRecz(dbzz: *sqli.Dbzz, vend: base.Vend, cred: u32, micr: u64, nowz: i64) !void { var stmt = try dbzz.prep("INSERT INTO vled(vend,mont,cred,micr) VALUES(?1,?2,?3,?4) ON CONFLICT(vend,mont) DO UPDATE SET cred=cred+?3, micr=micr+?4;"); defer stmt.fini(); try stmt.bindText(1, base.vendName(vend)); try stmt.bindIntz(2, montOfzz(nowz)); try stmt.bindIntz(3, cred); try stmt.bindIntz(4, @intCast(micr)); _ = try stmt.step(); }
